import time
import logging
import traceback
from taf.internal.managedobject import ManagedObject
from taf.internal.managed.ssh.managed_ssh_connection import ManagedSshConnection
from taf.ue.spark.api.facade import Spark
from taf.ue.spark.client.ue import UE, UEInfo
from taf.ue.spark.client.decorate import decorate_command_with_response_state_check
from taf.ue.spark.client.exception import NoUEConnectedError, NoUEWithIMSI, PrepareUENotCalledInAdvance
from taf.ue.spark.client.env import RemoteWindowsEnvironment
from taf.ue.spark.client.adb import ADB


class SparkService(ManagedObject):
    def __init__(self, host, port=None, ssh_port=None, ssh_username=None, ssh_password=None, timeout=None):
        super(SparkService, self).__init__()
        self._spark = Spark(host, port)
        self._decorate_command_execute(self._spark.commands)
        self._timeout = timeout or 60
        self._ues_info = []
        self._ssh_port = ssh_port or 22
        self._ssh_username = ssh_username
        self._ssh_password = ssh_password
        self.add_prerequisite(self._spark)
        self._ssh_executor = self._create_ssh_connection()
        self._service_adb = ADB(self._ssh_executor)

    @property
    def adb(self):
        return self._service_adb

    def _create_ssh_connection(self):
        return ManagedSshConnection(
            host=self._spark.host,
            user=self._ssh_username,
            password=self._ssh_password,
            port=self._ssh_port).ssh_connection

    def get_pid_for_listening_port(self):
        cnn = self._create_ssh_connection()
        cnn.connect()
        env = RemoteWindowsEnvironment(cnn)
        pid = env.get_pid_for_listening_port(self._spark.port)
        cnn.disconnect()
        return pid

    def is_spark_pid(self, pid):
        cnn = self._create_ssh_connection()
        cnn.connect()
        env = RemoteWindowsEnvironment(cnn)
        result = env.is_app_pid(pid, "Spark.exe")
        cnn.disconnect()
        return result

    def _decorate_command_execute(self, commands):
        for command in commands:
            decorated = decorate_command_with_response_state_check(command.execute)
            setattr(command, "execute", decorated)

    def _setup(self):
        try:
            self._ssh_executor.connect()
        except Exception as e:
            logging.warning("default ssh connection failed for exception {}, {}. \r\n "
                            "will impact the ssh relevant keywords".format(e, traceback.format_exc()))

    def _teardown(self):
        self._disconnect_ues(timeout=self._timeout)
        self._ssh_executor.disconnect()

    def _get_ue_count(self, timeout=None):
        return self._spark.AutoCheck(until_timeout=timeout).bean.Param.Count

    def _connect_ues(self, timeout=None):
        self._spark.ConnectEQ(until_timeout=timeout)
        logging.debug("WA, wait 20s for spark stable after connecteq")
        time.sleep(20)  # WA for unstable connecteq, if the escape is no enough, the next next command maybe abnormal

    def _disconnect_ues(self, timeout=None):
        self._spark.DisConnectEQ(until_timeout=timeout)

    def prepare_ues(self):
        self._connect_ues(timeout=self._timeout)
        return self.refresh_ues_info(timeout=self._timeout)

    def release_ues(self):
        self._disconnect_ues(timeout=self._timeout)
        self._ues_info = []

    def refresh_ues_info(self, timeout):
        self._ues_info = []
        ue_count = self._get_ue_count()
        if not ue_count:
            raise NoUEConnectedError()
        for eqindex in range(1, ue_count + 1):
            ue_info = self._retrive_ue_info(eqindex)
            self._ues_info.append(ue_info)
        return self._ues_info

    def _retrive_ue_info(self, eqindex, timeout=None):
        imsi = self._spark.GetParamIMSI(eqindex, until_timeout=timeout).bean.Param.IMSI
        if not imsi:
            # for ue without SIM card
            logging.warning("no imsi was got from eqindex {} device".format(eqindex))
        return UEInfo(eqindex=eqindex, imsi=imsi)

    @property
    def ues_info(self):
        return self._ues_info

    def _connect_one_ue(self, eqindex, timeout=None):
        if not eqindex:
            raise AttributeError("eqindex must start from 1")
        self._spark.ConnectOneEQ(eqindex=eqindex, until_timeout=timeout)

    def _disconnect_one_ue(self, eqindex, timeout=None):
        if not eqindex:
            raise AttributeError("eqindex must start from 1")
        self._spark.DisConnectOneEQ(eqindex=eqindex, until_timeout=timeout)

    def require_ue_from_eqindex(self, eqindex=1, serial_number=None):
        ue_info = self._find_ue_info_from_eqindex(eqindex)
        if not ue_info:
            self._connect_one_ue(eqindex)
            ue_info = self._retrive_ue_info(eqindex)
        self._ues_info.append(ue_info)
        adb = ADB(self._ssh_executor, serial_number)
        return UE(self._spark, adb, self._ues_info[0], self)

    def _find_ue_info_from_eqindex(self, eqindex):
        if eqindex < 1:
            raise AttributeError("eqindex must start from 1")

        for ue_info in self._ues_info:
            if ue_info.eqindex == eqindex:
                return ue_info
        return None

    def require_ue(self, serial_number=None, imsi=None):
        if not imsi:
            return self.require_ue_from_eqindex(eqindex=1)

        for ue_info in self._ues_info:
            if ue_info.imsi == imsi:
                adb = ADB(self._ssh_executor, serial_number)
                return UE(self._spark, adb, ue_info, self)
        raise NoUEWithIMSI("imsi {} is absent".format(imsi))

    def release_ue(self, ue):
        self._disconnect_one_ue(ue.eqindex)
        self._ues_info.remove(self._find_ue_info_from_eqindex(ue.eqindex))

    def start_log(self, logpath, logname, timeout=None):
        return self._spark.StartLog(logpath, logname, until_timeout=timeout)

    def stop_log(self, timeout=None):
        return self._spark.StopLog(until_timeout=timeout)

    def export_log_file(self, templatename, exportfilename, logfile, timeout=None):
        return self._spark.ExportLogFile(templatename,
                                         exportfilename,
                                         logfile,
                                         until_timeout=timeout)

    def export_message_detail(self, exportfilename, logfile, timeout=None):
        return self._spark.ExportMessageDetail(exportfilename, logfile, until_timeout=timeout)

    @staticmethod
    def _download_file(remote_path, connection, local_path):
        fp = connection.files
        log_msg = "Downloading file to {}:\n"
        log_msg += "Remote path: {}"
        log_msg = log_msg.format(connection, remote_path)
        logging.info(log_msg)

        logging.info("Downloading file: {}".format(local_path))
        fp.get(remote_path, local_path)

    def download_file(self, remote_src_file, local_dest_file):
        self._download_file(remote_src_file, self._ssh_executor, local_dest_file)

    def remove_remote_files(self, folder_path):
        return self._ssh_executor.execute("rm -f {}/*".format(folder_path))
